begin;
do $$
declare owner_email text; saved jsonb; challenge jsonb; login jsonb; result jsonb; aid uuid; i int;
 player text:='manual-auth-transaction-test'; hash text:=repeat('a',64); salt text:=repeat('b',64);
begin
 select email into owner_email from nova_evidence_private.hub_staff where role='master' and status='active' and accounts_manage limit 1;
 if owner_email is null then raise exception 'No test operator';end if;
 if has_function_privilege('anon','public.nova_manual_accounts(text,jsonb)','EXECUTE') or has_function_privilege('authenticated','public.nova_manual_accounts(text,jsonb)','EXECUTE') then raise exception 'Public RPC access';end if;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='nova_evidence_private' and c.relname in ('manual_accounts','manual_sessions','manual_login_limits') and not c.relrowsecurity) then raise exception 'RLS missing';end if;
 insert into transfer_private.portal_records(kind,key,revision,payload) values('players',player,1,jsonb_build_object('name','Transactional test','alliance','NvSP','server','1616'));
 begin perform public.nova_manual_accounts('hub-login-search',jsonb_build_object('staffEmail','unauthorized@example.invalid','query','test'));raise exception 'Owner check bypassed';exception when raise_exception then if sqlerrm<>'Access denied' then raise;end if;end;
 saved:=public.nova_manual_accounts('hub-login-save',jsonb_build_object('staffEmail',owner_email,'playerKey',player,'username','transaction_test_only','hash',hash,'salt',salt,'reason','Transaction test'));
 aid:=(saved->>'id')::uuid;
 challenge:=public.nova_manual_accounts('login-begin','{"username":"transaction_test_only","ip":"transaction-test"}');
 if challenge->>'hash' is distinct from hash then raise exception 'Saved hash mismatch';end if;
 login:=public.nova_manual_accounts('login-finish',jsonb_build_object('accountId',aid,'version',challenge->'version'));
 if login->>'token' is null then raise exception 'Login failed';end if;
 result:=public.nova_manual_accounts('session',jsonb_build_object('token',login->>'token'));
 if result->'user'->>'id' is distinct from aid::text or result->'user'->>'leaderEmail' is not null then raise exception 'Member identity incorrect';end if;
 perform public.nova_manual_accounts('hub-login-save',jsonb_build_object('staffEmail',owner_email,'accountId',aid,'playerKey',player,'username','transaction_test_only','hash',repeat('c',64),'salt',salt,'reason','Reset test password'));
 result:=public.nova_manual_accounts('session',jsonb_build_object('token',login->>'token'));
 if result->>'error' is distinct from 'invalid_session' then raise exception 'Old session survives reset';end if;
 result:=public.nova_manual_accounts('login-finish',jsonb_build_object('accountId',aid,'version',challenge->'version'));
 if result->>'error' is distinct from 'invalid_login' then raise exception 'Stale login race';end if;
 insert into nova_evidence_private.hub_staff(email,role,alliances,status,accounts_manage,updated_by) values('manual-test@example.invalid','r4','["NvSP"]','active',false,owner_email);
 insert into nova_evidence_private.admin_identities(email,id,display_name,player_key,revision,updated_at,updated_by) values('manual-test@example.invalid',gen_random_uuid(),'Transactional leader',player,1,now(),owner_email);
 perform public.nova_manual_accounts('hub-login-save',jsonb_build_object('staffEmail',owner_email,'accountId',aid,'playerKey',player,'targetEmail','manual-test@example.invalid','username','transaction_test_only','hash',hash,'salt',salt,'reason','Assign leader login'));
 challenge:=public.nova_manual_accounts('login-begin','{"username":"transaction_test_only","ip":"transaction-test"}');
 login:=public.nova_manual_accounts('login-finish',jsonb_build_object('accountId',aid,'version',challenge->'version'));
 if login->'user'->>'leaderEmail' is distinct from 'manual-test@example.invalid' then raise exception 'Leader identity missing';end if;
 update nova_evidence_private.hub_staff set status='revoked' where email='manual-test@example.invalid';
 result:=public.nova_manual_accounts('session',jsonb_build_object('token',login->>'token'));
 if result->'user'->>'leaderEmail' is not null then raise exception 'Revoked leader retains hub identity';end if;
 perform public.nova_manual_accounts('hub-login-disable',jsonb_build_object('staffEmail',owner_email,'accountId',aid));
 result:=public.nova_manual_accounts('login-begin','{"username":"transaction_test_only","ip":"transaction-test"}');
 if result->>'hash' is not null then raise exception 'Disabled account authenticates';end if;
 for i in 1..11 loop result:=public.nova_manual_accounts('login-begin','{"username":"unknown_transaction_test","ip":"transaction-test"}');end loop;
 if result->>'error' is distinct from 'try_later' then raise exception 'No brute-force limit';end if;
 if exists(select 1 from nova_evidence_private.hub_audit where subject=aid::text and detail::text like '%'||hash||'%') then raise exception 'Audit contains password hash';end if;
end; $$;
rollback;
select 'PASS: owner authorization, RLS, creation, identity, leadership permission revocation, reset revocation, stale-login rejection, disable, rate limits, audit privacy; all test data rolled back' as verification;
